export default function Testimonial() {
  return (
    <main className="relative bg-black min-h-screen m-7 rounded-3xl flex flex-col p-20 gap-16 shadow-xl overflow-hidden">
      <div className="flex justify-between items-start">
        <div className="flex flex-col gap-4">
          <h1 className="text-5xl font-bold text-white">Apa kata mereka?</h1>
          <p className="text-gray-300 text-lg">
            Berikut adalah testimonial dari orang tua siswa yang telah mengikuti
            program kami.
          </p>
        </div>

        <div className="flex gap-4 mt-6">
          <button className="w-14 h-14 rounded-full bg-white text-black flex items-center justify-center text-xl">
            ←
          </button>
          <button className="w-14 h-14 rounded-full bg-white text-black flex items-center justify-center text-xl">
            →
          </button>
        </div>
      </div>

      <div className="flex flex-row items-center justify-between gap-8 overflow-x-scroll overflow-y-hidden">
        {data.map((item, index) => (
          <div
            key={index}
            className="w-[420px] h-[360px] bg-white rounded-3xl p-8 shadow-lg flex flex-col shrink-0"
          >
            {/* HEADER */}
            <div className="flex items-center gap-4 h-[72px]">
              <div className="w-14 h-14 rounded-full bg-gray-200 flex-shrink-0" />
              <div className="overflow-hidden">
                <h3 className="font-bold text-lg text-black leading-tight line-clamp-1">
                  {item.name}
                </h3>
                <p className="text-sm text-gray-600 line-clamp-1">
                  {item.role}
                </p>
              </div>
            </div>

            {/* RATING */}
            <div className="mt-4 h-[28px] text-yellow-400">
              {"⭐".repeat(item.rating)}
            </div>

            {/* TESTIMONIAL */}
            <p className="mt-4 text-black text-sm leading-relaxed line-clamp-4">
              {item.testimonial}
            </p>
          </div>
        ))}
      </div>
    </main>
  );
}
